content.text:
{
  "primary_meaning": "Jesus Christ as the conquering Lion of the tribe of Judah, symbolizing royal power, strength, majesty, and victory",
  "primary_basis": [
    "Revelation 5:5",
    "Genesis 49:9-10"
  ],
  "alternatives": [
    {
      "meaning": "Satan/the devil as a roaring lion seeking to devour",
      "basis": [
        "1 Peter 5:8"
      ],
      "prominence": "common"
    },
    {
      "meaning": "General emblem of strength, courage, ferocity, or royal majesty (applied to persons, nations, or qualities)",
      "basis": [
        "Proverbs 28:1",
        "2 Samuel 1:23",
        "Psalms (various)",
        "Numbers 23:24"
      ],
      "prominence": "common"
    },
    {
      "meaning": "One of the four living creatures (often linked in tradition to a Gospel writer, especially Mark)",
      "basis": [
        "Revelation 4:7",
        "Ezekiel 1:10"
      ],
      "prominence": "common"
    },
    {
      "meaning": "God's fierce judgment or wrath",
      "basis": [
        "Hosea 5:14",
        "Amos 3:8",
        "Isaiah 31:4",
        "Lamentations 3:10"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": false,
  "confidence": "high",
  "notes": "Christian interpretation recognizes multiple well-attested symbolic uses rather than a single exclusive meaning; the Christological Lion of Judah is the most iconic positive usage, while the Satanic roaring lion is the most common negative counterpart, both widely taught."
}
